#include<iostream>
#include<iterator>

struct S
{
  void m() & 
  {
    std::cout << "&\n";
  }

  void m() && 
  {
    std::cout << "&&\n";
  }
};

int main()
{
  S x[1];
  std::move_iterator<S*>a{x};
  a->m();
  (*a).m();
}

namespace std {
